CREATE TABLE "pets" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "nome" TEXT NOT NULL, "especie" TEXT NOT NULL, "sexo" TEXT NOT NULL, "idade_meses" INTEGER NOT NULL, "idade_informada_em" INTEGER NOT NULL, "castrado" INTEGER NOT NULL CHECK ("castrado" IN (0, 1)), "nivel_atividade" TEXT NOT NULL, "foto_arquivo" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "alimentos" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "nome" TEXT NOT NULL, "densidade_kcal_por100g" REAL NOT NULL, "porcao_padrao_g" REAL NOT NULL, "arquivado" INTEGER NOT NULL DEFAULT 0 CHECK ("arquivado" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "refeicoes" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "alimento_id" TEXT NULL, "alimento_nome" TEXT NOT NULL, "densidade_kcal_por100g" REAL NOT NULL, "quantidade_g" REAL NOT NULL, "energia_kcal" REAL NOT NULL, "data_hora" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "extras" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "descricao" TEXT NOT NULL, "quantidade_g" REAL NULL, "energia_kcal" REAL NOT NULL, "data_hora" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "atividades" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "tipo" TEXT NOT NULL, "duracao_min" INTEGER NOT NULL, "data_hora" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "lembretes" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "hora" INTEGER NOT NULL, "tipo" TEXT NOT NULL, "ativo" INTEGER NOT NULL DEFAULT 1 CHECK ("ativo" IN (0, 1)), "notificacao_id" INTEGER NOT NULL UNIQUE, PRIMARY KEY ("id"));
CREATE TABLE "pesagens" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "peso_kg" REAL NOT NULL, "data_hora" INTEGER NOT NULL, "conferida" INTEGER NOT NULL DEFAULT 0 CHECK ("conferida" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "referencias" ("id" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, "versao" INTEGER NOT NULL DEFAULT 1, "versao_remota" INTEGER NULL, "estado_sync" TEXT NOT NULL DEFAULT 'local', "excluido" INTEGER NOT NULL DEFAULT 0 CHECK ("excluido" IN (0, 1)), "pet_id" TEXT NOT NULL REFERENCES pets (id) ON DELETE CASCADE, "ecc" INTEGER NULL, "objetivo_kg" REAL NULL, "origem" TEXT NOT NULL, "data" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "fila_sync" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "tabela" TEXT NOT NULL, "registro_id" TEXT NOT NULL, "operacao" TEXT NOT NULL, "criado_em" INTEGER NOT NULL, "tentativas" INTEGER NOT NULL DEFAULT 0, "ultimo_erro" TEXT NULL);
CREATE TABLE "conflitos" ("tabela" TEXT NOT NULL, "registro_id" TEXT NOT NULL, "dados_remotos" TEXT NOT NULL, "detectado_em" INTEGER NOT NULL, PRIMARY KEY ("tabela", "registro_id"));
CREATE TABLE "config" ("chave" TEXT NOT NULL, "valor" TEXT NULL, PRIMARY KEY ("chave"));
CREATE INDEX idx_alimentos_pet ON alimentos (pet_id);
CREATE INDEX idx_refeicoes_pet_data ON refeicoes (pet_id, data_hora);
CREATE INDEX idx_extras_pet_data ON extras (pet_id, data_hora);
CREATE INDEX idx_atividades_pet_data ON atividades (pet_id, data_hora);
CREATE INDEX idx_lembretes_pet ON lembretes (pet_id);
CREATE INDEX idx_pesagens_pet_data ON pesagens (pet_id, data_hora);
CREATE INDEX idx_referencias_pet ON referencias (pet_id);
CREATE INDEX idx_fila_sync_registro ON fila_sync (tabela, registro_id);
